// Group by query, and carry enough with each group to judge it later.
//
// Both Search Console windows are read by name rather than from the input,
// because the Merge above is only there to make sure both have finished.
const cfg = $('Settings').first().json;
const minImp = Math.max(1, Number(cfg.min_impressions) || 10);
const maxChars = Math.max(20, Number(cfg.max_query_chars) || 80);

function rowsOf(payload) {
  const p = (payload && payload.rows) ? payload : ((payload && payload.body) || {});
  return p.rows || [];
}

const now = rowsOf($('Ask Search Console').first().json);
const then = rowsOf($('Ask The Window Before').first().json);

if (!now.length) {
  throw new Error('Search Console returned no rows for ' + cfg.property + '. Check the property id and that the service account is a user on it.');
}

const priorByQuery = new Map();
for (const r of then) {
  const q = String(r.keys[0]);
  priorByQuery.set(q, (priorByQuery.get(q) || 0) + (r.impressions || 0));
}

const byQuery = new Map();
for (const r of now) {
  const q = String(r.keys[0]);
  const page = String(r.keys[1]);
  if (!byQuery.has(q)) { byQuery.set(q, new Map()); }
  const pages = byQuery.get(q);
  const seen = pages.get(page) || { url: page, impressions: 0, clicks: 0, position: 0 };
  seen.impressions += r.impressions || 0;
  seen.clicks += r.clicks || 0;
  seen.position = Math.round((r.position || 0) * 10) / 10;
  pages.set(page, seen);
}

const OPERATORS = /\b(site:|inurl:|intitle:|intext:|filetype:|cache:|related:)/i;

const out = [];
for (const [query, pages] of byQuery) {
  if (pages.size < 2) { continue; }
  const urls = [...pages.values()].sort(function (a, b) { return b.impressions - a.impressions; });
  const impressions = urls.reduce(function (t, u) { return t + u.impressions; }, 0);
  const clicks = urls.reduce(function (t, u) { return t + u.clicks; }, 0);
  if (impressions < minImp) { continue; }
  out.push({ json: {
    query: query,
    impressions: impressions,
    clicks: clicks,
    prior_impressions: priorByQuery.get(query) || 0,
    url_count: urls.length,
    urls: urls.slice(0, 6),
    // An operator query is not a keyword. `site:organikpi.com` came back as one
    // query carrying 87 URLs, which is the top row of every naive report.
    is_operator: OPERATORS.test(query),
    // AI Mode fan-out prompts are long, first-person and never clicked. On the
    // property this was measured against, every one of them was over 80
    // characters with zero clicks and every real query was under 60.
    looks_like_prompt: query.length >= maxChars && clicks === 0,
  }});
}

// A filtering step that can return nothing ends the branch, and the quiet path
// below would never fire. One marker item always comes back; it carries no
// query, so the IF downstream routes it to the quiet branch.
if (!out.length) {
  return [{ json: { query: '', impressions: 0, url_count: 0, urls: [], is_operator: false, looks_like_prompt: false } }];
}
return out.sort(function (a, b) { return b.impressions - a.impressions; });

// One item per distinct URL, not per pair. A page that shows up on nine
// overlapping queries is still one page, and fetching it nine times is nine
// requests to your own site for the same answer.
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  for (const u of (item.json.urls || [])) {
    const url = String(u.url || '');
    if (!url || seen.has(url)) { continue; }
    seen.add(url);
    out.push({ json: { url: url } });
  }
}
if (!out.length) { return [{ json: { url: '' } }]; }
return out.slice(0, 80);

// What the server and the head of the document claim about each URL.
//
// The fetch above does not follow redirects, which is the only way to see the
// 301 - and the 301 is what settles most of these. The HTTP Request node
// follows redirects by default on v4, so this needs saying out loud.
const asked = $('List Every URL Once').all();
const got = $input.all();

if (asked.length !== got.length) {
  throw new Error('Asked for ' + asked.length + ' URLs and got ' + got.length + ' responses. They are matched by position.');
}

function origin(u) {
  const m = String(u).match(/^https?:\/\/[^\/]+/);
  return m ? m[0] : '';
}

const out = [];
for (let i = 0; i < got.length; i++) {
  const url = String(((asked[i] || {}).json || {}).url || '');
  if (!url) { continue; }
  const j = got[i].json || {};
  const headers = j.headers || {};
  const body = typeof j.body === 'string' ? j.body : '';
  const status = Number(j.statusCode || 0);

  let location = String(headers.location || headers.Location || '');
  if (location && location.charAt(0) === '/') { location = origin(url) + location; }

  const canonTag = body.match(/<link[^>]+rel=["']canonical["'][^>]*>/i);
  const canonical = canonTag ? ((canonTag[0].match(/href=["']([^"']+)["']/i) || [])[1] || '') : '';

  const alternates = [];
  for (const m of body.matchAll(/<link[^>]+rel=["']alternate["'][^>]*>/gi)) {
    if (!/hreflang=/i.test(m[0])) { continue; }
    const href = (m[0].match(/href=["']([^"']+)["']/i) || [])[1];
    if (href) { alternates.push(href); }
  }

  out.push({ json: {
    url: url,
    status: status,
    redirects_to: location,
    canonical: canonical,
    alternates: alternates.slice(0, 40),
  }});
}
if (!out.length) { return [{ json: { url: '', status: 0 } }]; }
return out;

// Judge every pair against what the URLs themselves say.
//
// Four things look identical to a group-by and are not the same problem:
//   redirect  - one URL 301s to the other. Search Console reports the old path
//               for weeks after a move, so this is the common case, and there
//               is nothing to consolidate: it is already consolidated.
//   canonical - one page names the other as canonical. Declared duplicate.
//   alternate - the two are hreflang alternates, or the same path under a
//               locale prefix. Different languages of one page.
//   real      - none of the above. Two pages, one intent.
const cfg = $('Settings').first().json;
const prefixes = String(cfg.locale_prefixes || '')
  .split(',')
  .map(function (p) { return p.trim().replace(/^\/|\/$/g, ''); })
  .filter(Boolean);

const facts = new Map();
for (const f of $('Read What Each URL Is').all()) {
  if (f.json.url) { facts.set(norm(f.json.url), f.json); }
}

function norm(u) {
  return String(u || '').split('#')[0].split('?')[0].replace(/\/$/, '').toLowerCase();
}

function pathOf(u) {
  return norm(u).replace(/^https?:\/\/[^\/]+/, '');
}

function stripLocale(p) {
  for (const pre of prefixes) {
    if (p === '/' + pre) { return '/'; }
    if (p.indexOf('/' + pre + '/') === 0) { return p.slice(pre.length + 1); }
  }
  return p;
}

const seenBefore = new Map();
for (const row of $('Read What You Reported').all()) {
  const r = row.json || {};
  if (r.pair_key) { seenBefore.set(String(r.pair_key), r); }
}

const today = new Date().toISOString().slice(0, 10);
const out = [];

// Read the candidates by name, not from the input. Three branches feed the
// Merge above and it is there only to prove they have all finished: the URL
// facts and the reported history arrive on it too. A stored history row has a
// `query` column and a `urls` column holding a string, and a string has a
// length - so reading the merged stream turned one old row into a phantom
// candidate whose two "URLs" were the first two characters of a URL list.
for (const item of $('Drop The AI Mode Prompts').all()) {
  const c = item.json;
  if (!c.query || !Array.isArray(c.urls) || c.urls.length < 2) { continue; }

  const a = c.urls[0];
  const b = c.urls[1];
  const fa = facts.get(norm(a.url)) || {};
  const fb = facts.get(norm(b.url)) || {};

  let verdict = 'real';
  let why = '';

  const aRedirects = fa.status >= 300 && fa.status < 400 && norm(fa.redirects_to) === norm(b.url);
  const bRedirects = fb.status >= 300 && fb.status < 400 && norm(fb.redirects_to) === norm(a.url);
  if (aRedirects || bRedirects) {
    verdict = 'redirect';
    why = (aRedirects ? a.url : b.url) + ' already redirects to the other. Search Console keeps reporting a moved URL for weeks.';
  } else if (norm(fa.canonical) === norm(b.url) || norm(fb.canonical) === norm(a.url)) {
    verdict = 'canonical';
    why = 'One of the two names the other as its canonical, so they are already declared the same page.';
  } else if (
    (fa.alternates || []).some(function (x) { return norm(x) === norm(b.url); }) ||
    (fb.alternates || []).some(function (x) { return norm(x) === norm(a.url); }) ||
    (stripLocale(pathOf(a.url)) === stripLocale(pathOf(b.url)) && pathOf(a.url) !== pathOf(b.url))
  ) {
    verdict = 'alternate';
    why = 'These are language or region versions of one page, not two pages after one query.';
  }

  const prior = Number(c.prior_impressions) || 0;
  const trend = prior === 0
    ? 'new'
    : (c.impressions > prior * 1.2 ? 'growing' : (c.impressions < prior * 0.8 ? 'fading' : 'steady'));

  const pairKey = (norm(c.query) + ' :: ' + [norm(a.url), norm(b.url)].sort().join(' | ')).slice(0, 240);
  const before = seenBefore.get(pairKey);
  // Reported once already, and not meaningfully bigger since. Saying it again
  // every Monday is how a weekly digest stops being read.
  const stale = before && c.impressions < Number(before.impressions || 0) * 1.5;

  out.push({ json: {
    pair_key: pairKey,
    query: c.query,
    verdict: verdict,
    why: why,
    trend: trend,
    impressions: c.impressions,
    clicks: c.clicks,
    prior_impressions: prior,
    urls: [a, b],
    url_count: c.url_count,
    is_new: !before,
    report: verdict === 'real' && !stale,
    last_seen: today,
  }});
}

if (!out.length) {
  return [{ json: { pair_key: '', query: '', verdict: 'none', report: false, impressions: 0, urls: [] } }];
}
return out;

// One prompt for the whole shortlist, not one per pair. A pair costs two lines
// of context, and ten separate calls buy ten identical system prompts.
const rows = $input.all().map(function (i) { return i.json; });
const lines = rows.slice(0, 12).map(function (r, n) {
  const u = r.urls.map(function (x) {
    return '   - ' + x.url + '  (' + x.impressions + ' impressions, ' + x.clicks + ' clicks, average position ' + x.position + ')';
  }).join('\n');
  return (n + 1) + '. "' + r.query + '"  [' + r.trend + ', ' + r.impressions + ' impressions total]\n' + u;
});

return [{ json: {
  count: rows.length,
  block: lines.join('\n\n'),
  keys: rows.slice(0, 12).map(function (r) { return r.pair_key; }),
}}];

// Merge the model's line back onto the row it belongs to, by position.
//
// single-item input: one call covered the whole shortlist.
const shortlist = $('Write The Shortlist').first().json;
const raw = String(($input.first().json || {}).text || '');

let parsed = {};
const s = raw.indexOf('{');
const e = raw.lastIndexOf('}');
if (s >= 0 && e > s) {
  try { parsed = JSON.parse(raw.slice(s, e + 1)); } catch (err) { parsed = {}; }
}

const advice = new Map();
for (const row of (parsed.pairs || [])) {
  const n = Number(row && row.number);
  if (n >= 1 && n <= shortlist.keys.length) {
    advice.set(shortlist.keys[n - 1], {
      keep: String((row && row.keep) || '').slice(0, 300),
      action: String((row && row.action) || '').slice(0, 300),
    });
  }
}

const rows = $('Only The Real Ones').all().map(function (i) { return i.json; });
return rows.map(function (r) {
  const a = advice.get(r.pair_key) || { keep: '', action: '' };
  return { json: Object.assign({}, r, {
    keep_url: a.keep,
    action: a.action || 'No recommendation came back for this one - the pair is still real.',
    urls_text: r.urls.map(function (u) { return u.url; }).join(' | '),
  })};
});

// The branches that end here are not failures, they are the answer: this pair
// is one page. Counting them is what lets the digest say how much of the report
// was noise, which is the number that makes the rest believable.
//
// single-item input: only the verdict is read, and every item on this branch
// carries the same one - that is what the Switch above sorted them by.
const kind = $input.first().json.verdict;
return [{ json: { verdict: kind, ruled_out: $input.all().length } }];

// The branches that end here are not failures, they are the answer: this pair
// is one page. Counting them is what lets the digest say how much of the report
// was noise, which is the number that makes the rest believable.
//
// single-item input: only the verdict is read, and every item on this branch
// carries the same one - that is what the Switch above sorted them by.
const kind = $input.first().json.verdict;
return [{ json: { verdict: kind, ruled_out: $input.all().length } }];

// What the week actually found, with the noise counted rather than hidden.
//
// The counts matter as much as the findings: "39 queries had two URLs on them
// and one of those is worth your time" is the finding. A list of 39 rows is a
// spreadsheet nobody opens twice.
const cfg = $('Settings').first().json;
const judged = $('Decide What Is Actually Overlapping').all().map(function (i) { return i.json; })
  .filter(function (r) { return r.query; });

const real = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r.query; });

function count(kind) {
  return judged.filter(function (r) { return r.verdict === kind; }).length;
}

// The raw count comes from before the two filters, because the gap between it
// and what was checked is the most useful number in the message: on the
// property this was built against it was 27 down to 20, and 20 down to 1.
const raw = $('Group Every Query By Its Pages').all().filter(function (i) { return i.json.query; });
const filtered = raw.length - judged.length;

function plural(n, one, many) { return n + ' ' + (n === 1 ? one : many); }

const parts = ['*Query overlaps on ' + cfg.property + '*'];
parts.push(raw.length + ' queries had more than one of your URLs on them over the last ' + cfg.days + ' days.');
if (filtered > 0) {
  parts.push(plural(filtered, 'was an operator query or an AI Mode prompt', 'were operator queries or AI Mode prompts') + ', which are not keywords anybody typed.');
}

const skipped = [];
if (count('redirect')) { skipped.push(plural(count('redirect'), 'is one page under two URLs', 'are one page under two URLs') + ', one already redirecting to the other'); }
if (count('canonical')) { skipped.push(plural(count('canonical'), 'names the other as canonical', 'name the other as canonical')); }
if (count('alternate')) { skipped.push(plural(count('alternate'), 'is a language version of one page', 'are language versions of one page')); }
if (skipped.length) { parts.push('\nRuled out: ' + skipped.join('; ') + '.'); }

if (!real.length) {
  parts.push('\nNothing left that needs a decision.');
} else {
  parts.push('\n*' + real.length + ' worth a decision*');
  for (const r of real.slice(0, 10)) {
    const u = r.urls.map(function (x) { return '   ' + x.url + ' - position ' + x.position + ', ' + x.impressions + ' impressions'; }).join('\n');
    parts.push('\n*' + r.query + '* _(' + r.impressions + ' impressions, ' + r.trend + ')_\n' + u + '\n   ' + (r.keep_url ? 'Keep: ' + r.keep_url + '. ' : '') + r.action);
  }
}

return [{ json: { message: parts.join('\n'), real_count: real.length, checked: judged.length } }];
